import { BoldReport } from '../components/BoldReport';

const ReportsPage: React.FC = () => {
  return (
    <div>
      <h2>Team Event Report</h2>
      <BoldReport
        apiUrl="http://localhost:5000/api/reports/event-report" // Your API serving the RDL
        reportName="EventReport.rdl"
      />
    </div>
  );
};

export default ReportsPage;
